#include <iostream>
#include <vector>

int main() {
    std::vector<int> data = {5, 2, 9, 1, 7};
    int n = data.size();

    for (int i = 0; i < n - 1; i++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - i; j++) {
            if (data[j] > data[j + 1]) {
                int tmp = data[j];
                data[j] = data[j + 1];
                data[j + 1] = tmp;
                swapped = true;
            }
        }
        if (!swapped) {
            break;
        }
    }

    bool first = true;
    for (int v : data) {
        if (!first) std::cout << ' ';
        std::cout << v;
        first = false;
    }
    std::cout << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& arr, int target) {
    int lo = 0;
    int hi = arr.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    std::vector<int> data = {1, 3, 5, 7, 9, 11};
    std::cout << "find 9: index " << binarySearch(data, 9) << std::endl;
    std::cout << "find 4: index " << binarySearch(data, 4) << std::endl;
    return 0;
}

#include <iostream>

long long factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

int digitSum(int n) {
    if (n == 0) return 0;
    return n % 10 + digitSum(n / 10);
}

int main() {
    std::cout << "factorial(5) = " << factorial(5) << std::endl;
    std::cout << "digitSum(927) = " << digitSum(927) << std::endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> data = {7, 2, 9, 4, 5};

    int mn = data[0];
    int mx = data[0];
    for (int v : data) {
        if (v < mn) mn = v;
        if (v > mx) mx = v;
    }
    std::cout << "min: " << mn << " max: " << mx << std::endl;

    std::cout << std::min(3, 8) << ' ' << std::max(3, 8) << std::endl;

    auto lo = std::min_element(data.begin(), data.end());
    auto hi = std::max_element(data.begin(), data.end());
    std::cout << *lo << ' ' << *hi << ' ' << hi - data.begin() << std::endl;
    return 0;
}

#include <algorithm>
#include <functional>
#include <iostream>
#include <string>
#include <vector>

bool byLength(const std::string& a, const std::string& b) {
    return a.size() < b.size();
}

void show(const char* label, const std::vector<int>& v) {
    std::cout << label;
    bool head = true;
    for (int x : v) {
        if (!head) std::cout << ' ';
        std::cout << x;
        head = false;
    }
    std::cout << std::endl;
}

int main() {
    std::vector<int> nums = {5, 2, 9, 1, 7};
    std::sort(nums.begin(), nums.end());
    show("asc: ", nums);

    std::sort(nums.begin(), nums.end(), std::greater<int>());
    show("desc: ", nums);

    std::vector<std::string> words = {"pear", "fig", "apple"};
    std::sort(words.begin(), words.end(), byLength);
    std::cout << words[0] << ' ' << words[1] << ' ' << words[2] << std::endl;
    return 0;
}

#include <algorithm>
#include <functional>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<int> marks = {4, 5, 3, 5, 4};

    int sum = 0;
    for (int m : marks) {
        sum += m;
    }
    std::cout << "manual: " << sum << std::endl;

    int total = std::accumulate(marks.begin(), marks.end(), 0);
    std::cout << "accumulate: " << total << std::endl;

    double average = static_cast<double>(total) / marks.size();
    std::cout << "average: " << average << std::endl;

    int product = std::accumulate(marks.begin(), marks.end(), 1,
                                  std::multiplies<int>());
    std::cout << "product: " << product << std::endl;
    return 0;
}
